#!/usr/bin/env python3
"""microbiome/scfa_butyrate_screen_real — auto-generated run.py (archetype=microbiome_pipeline).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "microbiome_pipeline"
BRAIN = "microbiome"
SKILL = "scfa_butyrate_screen_real"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'scfa_butyrate_screen_real', 'n_samples': 0, 'taxonomy_table': '', 'diversity_metrics': {'shannon': 0.0, 'observed_otus': 0}, 'diagnostics': {'brain': 'microbiome', 'archetype': 'microbiome_pipeline'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """SCFA (butyrate) pathway 筛查:跑 humann 后从 pathabundance 抓 BUT/SCFA pathway。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    fq = payload.get("input_fastq") or payload.get("fastq_1")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="scfa_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "humann+scfa-filter", "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_samples": 0, "taxonomy_table": "",
                "diversity_metrics": {"shannon": 0.0, "observed_otus": 0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not fq or not _os.path.isfile(fq):
        return {"ok": False, "error": "需要 input_fastq", "diagnostics": diagnostics}
    t0 = _time.time()
    r = run_tool(["humann", "--input", fq, "--output", out_dir,
                  "--threads", str(payload.get("threads", 8))],
                 timeout=int(payload.get("timeout_s", 14400)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "humann 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    import glob as _glob
    path_tsvs = _glob.glob(_os.path.join(out_dir, "*_pathabundance.tsv"))
    scfa_keywords = ["BUT", "butyrate", "butanoate", "propanoate", "acetate", "SCFA"]
    scfa_hits = []
    if path_tsvs:
        with open(path_tsvs[0]) as fh:
            for ln in fh:
                if any(k.lower() in ln.lower() for k in scfa_keywords):
                    parts = ln.strip().split("\t")
                    if len(parts) >= 2:
                        try: scfa_hits.append({"pathway": parts[0], "abundance": float(parts[1])})
                        except ValueError: pass
    return {"ok": True, "skill_id": SKILL, "n_samples": 1,
            "taxonomy_table": path_tsvs[0] if path_tsvs else "",
            "diversity_metrics": {"shannon": 0.0, "observed_otus": len(scfa_hits)},
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "scfa_hits": scfa_hits[:30]}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
